import json
import re
from html.parser import HTMLParser
from pathlib import Path

from PIL import Image, ImageStat


TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / "CSX-276"
OUT_PATH = TASK_DIR / "computed_gt.json"


class TextExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts = []

    def handle_data(self, data):
        text = " ".join(data.split())
        if text:
            self.parts.append(text)

    def text(self):
        return "\n".join(self.parts)



REASONING_DEPTH = {'evidence_weighting': 'The image pair supports local surface appearance change, while ENSO indicators and the NOAA briefing carry the stronger drought-context weight.', 'counterfactual_rejection': 'A flood-damage or wildfire-smoke reading fails because the physical chain is ENSO-linked drought risk and the image signal is brighter and slightly less green.', 'uncertainty_or_scale_caveat': 'Two true-color dates cannot by themselves establish regional drought severity or agricultural loss magnitude.'}


def attach_reasoning_depth(result):
    reasoning = dict(REASONING_DEPTH)
    primary = result.get("primary_gt")
    if isinstance(primary, dict):
        primary["reasoning_depth"] = reasoning
    guidance = result.get("answer_guidance")
    if isinstance(guidance, dict):
        guidance["reasoning_depth"] = reasoning
    key_values = result.get("key_values")
    if isinstance(key_values, dict):
        key_values["reasoning_depth"] = reasoning
    rubric = result.get("rubric")
    if isinstance(rubric, dict):
        criteria = rubric.get("criteria")
        if isinstance(criteria, list) and criteria:
            addition = " Full credit also requires the `reasoning_depth` object to identify decisive evidence, reject the main tempting simplification, and state a bounded uncertainty or scale caveat."
            last = criteria[-1]
            desc = last.get("description", "")
            if addition.strip() not in desc:
                last["description"] = (desc.rstrip() + addition).strip()
    return result

def read_text(rel_path):
    return (PACKAGE_DIR / rel_path).read_text(encoding="utf-8", errors="replace")


def read_json(rel_path):
    return json.loads(read_text(rel_path))


def html_text(rel_path):
    parser = TextExtractor()
    parser.feed(read_text(rel_path))
    return parser.text()


def image_stats(rel_path):
    image = Image.open(PACKAGE_DIR / rel_path).convert("RGB")
    mean_r, mean_g, mean_b = ImageStat.Stat(image).mean
    total = mean_r + mean_g + mean_b
    return {
        "width": image.size[0],
        "height": image.size[1],
        "mean_red": round(mean_r, 3),
        "mean_green": round(mean_g, 3),
        "mean_blue": round(mean_b, 3),
        "brightness": round(total / 3.0, 3),
        "green_ratio": round(mean_g / total, 5),
    }


def parse_cpc_oni(rel_path):
    records = []
    for line in read_text(rel_path).splitlines():
        parts = line.split()
        if len(parts) == 4 and parts[1].isdigit():
            records.append(
                {
                    "season": parts[0],
                    "year": int(parts[1]),
                    "anomaly": float(parts[3]),
                }
            )
    return records


def parse_monthly_index(rel_path, years):
    records = []
    for line in read_text(rel_path).splitlines():
        parts = line.split()
        if len(parts) >= 13 and parts[0].isdigit() and int(parts[0]) in years:
            year = int(parts[0])
            for month, value in enumerate(parts[1:13], start=1):
                val = float(value)
                if val > -90:
                    records.append({"year": year, "month": month, "value": val})
    return records


def report_flags(text):
    lowered = text.lower()
    return {
        "three_strongest_el_nino": "three strongest" in lowered and "historical record" in lowered,
        "atmosphere_coupling_march_2015": "march 2015" in lowered and "officially underway" in lowered,
        "rainfall_pressure_disruptions_december_2015": "december 2015" in lowered
        and "temperature, rainfall, and surface air pressure" in lowered,
        "failed_rainy_seasons": "failed rainy seasons" in lowered,
        "drought_mentions": len(re.findall(r"\bdrought\b", lowered)),
    }


def build_rubric():
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "final_interpretation_label_and_stance",
                "points": 4,
                "description": (
                    "Identifies the result as contextual drier-surface or vegetation-stress support "
                    "under ENSO-linked drought caution, not standalone regional severity proof."
                ),
                "partial_credit": "Names drought stress but omits either the ENSO framing or the caution against standalone proof.",
            },
            {
                "name": "image_metric_extraction",
                "points": 4,
                "description": (
                    "Reports brightness delta near 7.72 and green-ratio delta near -0.00159, "
                    "with correct sign and interpretation."
                ),
                "partial_credit": "Gives one correct metric, correct direction with weaker rounding, or a qualitative image-change description.",
            },
            {
                "name": "enso_climate_context",
                "points": 4,
                "description": (
                    "Uses the very strong El Nino context, peak ONI near 2.75 C, negative SOI near -3.6, "
                    "and report-supported rainfall disruption or failed rainy seasons."
                ),
                "partial_credit": "Mentions a generic El Nino/drought link without enough quantitative or report anchors.",
            },
            {
                "name": "cross_scale_fusion_and_limitation",
                "points": 3,
                "description": (
                    "Integrates the image cue with climate-index/report evidence and explains why a two-date "
                    "true-color pair cannot prove regional drought severity alone."
                ),
                "partial_credit": "Combines image and climate evidence but gives only a vague limitation.",
            },
            {
                "name": "disaster_interpretation_and_operational_implication",
                "points": 2,
                "description": "Translates the result into cautious drought briefing or response-planning language.",
                "partial_credit": "Provides a general disaster-impact statement without explaining how the interpretation should be used.",
            },
            {
                "name": "rejection_of_unsupported_alternatives",
                "points": 2,
                "description": (
                    "Rejects flood damage, wildfire smoke, and definitive crop-loss or regional-severity claims "
                    "as unsupported by the physical chain."
                ),
                "partial_credit": "Rejects only one major distractor or rejects alternatives without physical justification.",
            },
            {
                "name": "output_clarity_and_source_discipline",
                "points": 1,
                "description": "Uses compact structured JSON or a clearly equivalent short answer and stays within the incident record.",
                "partial_credit": "Readable answer with minor formatting issues.",
            },
        ],
    }


def main():
    event = read_json("metadata/event.json")
    anchor = read_json(
        "data/event_reports/event_reports_002_Locked_event_anchor_2015-2016_El_Nino_and_Southern_Africa_drought.json"
    )
    report_text = html_text("data/event_reports/event_reports_001_Locked_anchor_NOAA_Climate.gov.html")
    pre = image_stats("data/remote_sensing/remote_sensing_002_pre.jpg")
    during = image_stats("data/remote_sensing/remote_sensing_003_event.jpg")
    cpc_oni = parse_cpc_oni("data/physical_hazard/physical_hazard_006_NOAA_CPC_ONI_ASCII.txt")
    event_oni = [record for record in cpc_oni if record["year"] in (2015, 2016)]
    soi = parse_monthly_index("data/physical_hazard/physical_hazard_008_NOAA_PSL_SOI_data.data", {2015, 2016})
    flags = report_flags(report_text)

    brightness_delta = round(during["brightness"] - pre["brightness"], 3)
    green_ratio_delta = round(during["green_ratio"] - pre["green_ratio"], 5)
    peak_oni = max(event_oni, key=lambda record: record["anomaly"])
    min_soi = min(soi, key=lambda record: record["value"])

    interpretation = "contextual_drier_surface_signal_with_enso_drought_caution"
    diagnostic_chain = [
        "event_image_brighter_and_slightly_less_green_than_pre_event_image",
        "very_strong_el_nino_and_negative_soi_support_enso_drought_risk_context",
        "true_color_pair_is_context_not_standalone_regional_drought_proof",
    ]

    source_files = [
        "metadata/event.json",
        "data/event_reports/event_reports_001_Locked_anchor_NOAA_Climate.gov.html",
        "data/event_reports/event_reports_002_Locked_event_anchor_2015-2016_El_Nino_and_Southern_Africa_drought.json",
        "data/physical_hazard/physical_hazard_006_NOAA_CPC_ONI_ASCII.txt",
        "data/physical_hazard/physical_hazard_008_NOAA_PSL_SOI_data.data",
        "data/remote_sensing/remote_sensing_002_pre.jpg",
        "data/remote_sensing/remote_sensing_003_event.jpg",
    ]

    structured_answer = {
        "interpretation": interpretation,
        "image_change": {
            "brightness_delta": round(brightness_delta, 2),
            "green_ratio_delta": green_ratio_delta,
        },
        "diagnostic_chain": [
            "event image is brighter and slightly less green than the pre-event image",
            "very strong El Nino conditions and negative SOI support an ENSO-linked drought-risk context",
            "the true-color pair is contextual support, not standalone proof of regional drought severity",
        ],
    }

    result = {
        "schema_version": "crossscale_extreme_event_bench_v1",
        "task_id": "CSX-276_Q2",
        "event_id": "CSX-276",
        "task_type": "short_answer",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": structured_answer,
        "answer_guidance": {
            "answer_type": "hybrid_structured_short_answer",
            "answer": interpretation,
            "canonical_stance": (
                "Contextual drier-surface or vegetation-stress image cue under strong ENSO drought risk; "
                "not standalone regional drought-severity proof."
            ),
            "required_claims": [
                "event_image_brighter_and_slightly_less_green",
                "strong_el_nino_negative_soi_failed_rains_context",
                "true_color_pair_context_only_not_severity_or_loss_proof",
            ],
            "required_metrics": [
                {
                    "name": "brightness_delta",
                    "value": brightness_delta,
                    "tolerance": 0.1,
                },
                {
                    "name": "green_ratio_delta",
                    "value": green_ratio_delta,
                    "tolerance": 0.0002,
                },
                {
                    "name": "peak_oni_anomaly_c",
                    "value": round(peak_oni["anomaly"], 2),
                    "tolerance": 0.05,
                },
                {
                    "name": "minimum_soi",
                    "value": round(min_soi["value"], 2),
                    "tolerance": 0.1,
                },
            ],
            "forbidden_claims": [
                "standalone_regional_drought_severity_proof",
                "flood_damage_primary_signal",
                "wildfire_smoke_primary_signal",
                "loss_or_soil_moisture_quantified_from_true_color_pair",
            ],
            "acceptable_variants": [
                "natural_language_label_ok",
                "brightness_7_7_or_7_72_green_ratio_about_minus_0_0016_ok",
            ],
        },
        "key_values": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "locked_location_text": anchor["spatial_window"]["location_text"],
            "event_window": anchor["temporal_window"],
            "pre_image_stats": pre,
            "event_image_stats": during,
            "brightness_delta": brightness_delta,
            "green_ratio_delta": green_ratio_delta,
            "diagnostic_chain": diagnostic_chain,
            "peak_oni_anomaly_c": round(peak_oni["anomaly"], 2),
            "peak_oni_season": f"{peak_oni['season']} {peak_oni['year']}",
            "oni_seasons_at_or_above_1_5_c": sum(1 for record in event_oni if record["anomaly"] >= 1.5),
            "minimum_soi": round(min_soi["value"], 2),
            "minimum_soi_month": f"{min_soi['year']}-{min_soi['month']:02d}",
            "report_flags": flags,
        },
        "rubric": build_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": source_files,
        },
    }

    attach_reasoning_depth(result)
    OUT_PATH.write_text(json.dumps(result, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(result["primary_gt"], indent=2))


if __name__ == "__main__":
    main()
